import React, {
  useEffect,
  useRef,
  useState,
  useCallback,
} from "react";
import Chart from "chart.js/auto";

const USAGE_PATH = "/smogon_csv/";
const MOVESET_PATH = "/csv_movesets/";
const POKE_PATH = "/pokemon_data/";

export default function ComUsage() {
  const chartRef = useRef(null);
  const canvasRef = useRef(null);

  const [usageFiles, setUsageFiles] = useState([]);
  const [movesetFiles, setMovesetFiles] = useState([]);

  const [pokemonList, setPokemonList] = useState([]);
  const [filteredList, setFilteredList] = useState([]);

  const [search, setSearch] = useState("");
  const [selectedPokemon, setSelectedPokemon] =
    useState(null);

  const [compareList, setCompareList] = useState([]);
  const [selectedGen, setSelectedGen] =
    useState("9");
  const [menuOpen, setMenuOpen] = useState(false);

  const [clickedBuild, setClickedBuild] =
    useState(null);

  // -----------------------------
  // Helpers
  // -----------------------------
  const normalize = (str) =>
    str?.toLowerCase().replace(/[^a-z0-9]/g, "") ||
    "";

  const getPokemonColor = (name) => {
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash =
        name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return `hsl(${Math.abs(hash) % 360},70%,50%)`;
  };

  const loadCSV = async (path) => {
    const res = await fetch(path);
    return await res.text();
  };

  const parseCSV = (text) =>
    text
      .trim()
      .split("\n")
      .slice(1)
      .map((r) =>
        r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
      );

  // Extract YYYY-MM from filename
  const extractMonth = (filename) => {
    const match = filename.match(/\d{4}-\d{2}/);
    return match ? match[0] : null;
  };

  // Auto-detect Smogon gen format:
  // supports:
  // gen9...
  // gen92v2...
  // gen9doubles...
  const matchesGen = (filename, gen) => {
    const lower = filename.toLowerCase();
    return lower.includes(`_gen${gen}`);
  };

  // Find exact month + gen file automatically
  const findMatchingFile = (
    fileList,
    month,
    gen
  ) => {
    return fileList.find((f) => {
      const lower = f.toLowerCase();
      return (
        lower.includes(
          `${month.toLowerCase()}_gen${gen}`
        )
      );
    });
  };

  // -----------------------------
  // Load File Lists
  // -----------------------------
  useEffect(() => {
    fetch(USAGE_PATH + "files.json")
      .then((res) => res.json())
      .then((data) => {
        console.log(
          "Usage Files Loaded:",
          data.files
        );
        setUsageFiles(data.files);
      });

    fetch(MOVESET_PATH + "files.json")
      .then((res) => res.json())
      .then((data) => {
        console.log(
          "Moveset Files Loaded:",
          data.files
        );
        setMovesetFiles(data.files);
      });
  }, []);

  // -----------------------------
  // Load Pokémon Names
  // -----------------------------
  useEffect(() => {
    const loadPokemonData = async () => {
      const text = await loadCSV(
        POKE_PATH + "pokemon_smogon_names.csv"
      );

      const rows = parseCSV(text);

      const list = rows.map((row) => ({
        display: row[0],
        smogon: row[1],
      }));

      setPokemonList(list);
      setFilteredList(list);
    };

    loadPokemonData();
  }, []);

  // -----------------------------
  // Default Selection
  // -----------------------------
  useEffect(() => {
    if (!selectedPokemon && pokemonList.length > 0) {
      setSelectedPokemon(pokemonList[0]);
    }
  }, [pokemonList, selectedPokemon]);

  // -----------------------------
  // Search Filter
  // -----------------------------
  useEffect(() => {
    const filtered = pokemonList.filter((p) =>
      normalize(p.display).includes(
        normalize(search)
      )
    );
    setFilteredList(filtered);
  }, [search, pokemonList]);

  // -----------------------------
  // Fix Invalid Selection
  // -----------------------------
  useEffect(() => {
    if (
      filteredList.length > 0 &&
      !filteredList.find(
        (p) =>
          p.display === selectedPokemon?.display
      )
    ) {
      setSelectedPokemon(filteredList[0]);
    }
  }, [filteredList, selectedPokemon]);

  // -----------------------------
  // Reset Build on Gen Change
  // -----------------------------
  useEffect(() => {
    setClickedBuild(null);
  }, [selectedGen]);

  // -----------------------------
  // Compare Actions
  // -----------------------------
  const addToCompare = () => {
    if (
      selectedPokemon &&
      !compareList.find(
        (p) =>
          p.display === selectedPokemon.display
      )
    ) {
      setCompareList([
        ...compareList,
        selectedPokemon,
      ]);
    }
  };

  const removeFromCompare = (name) => {
    setCompareList(
      compareList.filter((p) => p.display !== name)
    );
  };

  // -----------------------------
  // Load Pokémon Build
  // -----------------------------
  const loadPokemonBuild = useCallback(
    async (pokemonName, month) => {
      console.log(
        "Searching build for:",
        pokemonName,
        month
      );

      const targetFile = findMatchingFile(
        movesetFiles,
        month,
        selectedGen
      );

      console.log(
        "Matched moveset file:",
        targetFile
      );

      if (!targetFile) {
        setClickedBuild(null);
        return;
      }

      const text = await loadCSV(
        MOVESET_PATH + targetFile
      );

      const rows = parseCSV(text);

      const pokemonRows = rows.filter(
        (r) =>
          normalize(r[1]) ===
          normalize(pokemonName)
      );

      if (!pokemonRows.length) {
        setClickedBuild(null);
        return;
      }

      const grouped = {};

      for (let row of pokemonRows) {
        const category = row[2];
        const itemName = row[4];
        const usage = row[5];

        if (!grouped[category]) {
          grouped[category] = [];
        }

        grouped[category].push({
          name: itemName,
          usage,
        });
      }

      Object.keys(grouped).forEach((cat) => {
        grouped[cat] = grouped[cat]
          .sort(
            (a, b) =>
              Number(b.usage) - Number(a.usage)
          )
          .slice(0, 5);
      });

      setClickedBuild({
        pokemon: pokemonName,
        month,
        data: grouped,
      });
    },
    [movesetFiles, selectedGen]
  );

  // -----------------------------
  // Build Usage Data
  // -----------------------------
  const getUsageData = useCallback(async () => {
    const sortedFiles = usageFiles
      .filter((f) =>
        matchesGen(f, selectedGen)
      )
      .sort();

    const labels = sortedFiles.map((f) =>
      extractMonth(f)
    );

    const fileData = await Promise.all(
      sortedFiles.map(async (file) => {
        const text = await loadCSV(
          USAGE_PATH + file
        );
        return parseCSV(text);
      })
    );

    const datasets = [];

    for (let pokemonObj of compareList) {
      const data = [];

      for (let rows of fileData) {
        const match = rows.find(
          (r) =>
            normalize(r[0]) ===
            normalize(pokemonObj.smogon)
        );

        data.push(
          match && match[1]
            ? Number(match[1])
            : 0
        );
      }

      datasets.push({
        label: pokemonObj.display,
        data,
        borderColor: getPokemonColor(
          pokemonObj.display
        ),
        tension: 0.3,
        borderWidth: 2,
        pointRadius: 4,
        spanGaps: true,
      });
    }

    return { labels, datasets };
  }, [usageFiles, compareList, selectedGen]);

  // -----------------------------
  // Draw Chart
  // -----------------------------
  useEffect(() => {
    if (
      compareList.length === 0 ||
      !canvasRef.current
    ) {
      if (chartRef.current) {
        chartRef.current.destroy();
        chartRef.current = null;
      }
      return;
    }

    const buildChart = async () => {
      const { labels, datasets } =
        await getUsageData();

      if (chartRef.current) {
        chartRef.current.destroy();
      }

      chartRef.current = new Chart(
        canvasRef.current,
        {
          type: "line",
          data: { labels, datasets },
          options: {
            responsive: true,

            onClick: async (evt, elements) => {
              if (!elements.length) return;

              const point = elements[0];

              const pokemonName =
                datasets[
                  point.datasetIndex
                ].label;
              const month =
                labels[point.index];

              await loadPokemonBuild(
                pokemonName,
                month
              );
            },

            plugins: {
              legend: {
                position: "top",
              },
            },

            scales: {
              x: {
                title: {
                  display: true,
                  text: "Date",
                },
              },
              y: {
                title: {
                  display: true,
                  text: "Usage",
                },
                beginAtZero: true,
              },
            },
          },
        }
      );
    };

    buildChart();
  }, [
    compareList,
    getUsageData,
    loadPokemonBuild,
  ]);

  // -----------------------------
  // Cleanup
  // -----------------------------
  useEffect(() => {
    return () => {
      if (chartRef.current) {
        chartRef.current.destroy();
      }
    };
  }, []);

  // -----------------------------
  // UI
  // -----------------------------
  return (
    <div>
      <h2>Pokémon Usage Over Time</h2>

      <button
        onClick={() =>
          setMenuOpen(!menuOpen)
        }
      >
        ⚙️ Filters
      </button>

      {menuOpen && (
        <div
          style={{
            background: "#f5f5f5",
            padding: "15px",
            marginBottom: "20px",
          }}
        >
          <label>Generation:</label>
          <select
            value={selectedGen}
            onChange={(e) =>
              setSelectedGen(e.target.value)
            }
          >
            {[5, 6, 7, 8, 9].map((g) => (
              <option key={g} value={g}>
                Gen {g}
              </option>
            ))}
          </select>

          <br />
          <br />

          <input
            type="text"
            value={search}
            onChange={(e) =>
              setSearch(e.target.value)
            }
            placeholder="Search Pokémon"
          />

          <br />
          <br />

          <select
            size="5"
            value={
              selectedPokemon?.display || ""
            }
            onChange={(e) =>
              setSelectedPokemon(
                filteredList.find(
                  (p) =>
                    p.display ===
                    e.target.value
                )
              )
            }
          >
            {filteredList.map((p) => (
              <option key={p.display}>
                {p.display}
              </option>
            ))}
          </select>

          <br />
          <br />

          <button onClick={addToCompare}>
            Add to Compare
          </button>

          <hr />

          {compareList.map((p) => (
            <div key={p.display}>
              {p.display}
              <button
                onClick={() =>
                  removeFromCompare(p.display)
                }
              >
                X
              </button>
            </div>
          ))}
        </div>
      )}

      {clickedBuild && (
        <div
          style={{
            marginBottom: "20px",
            padding: "15px",
            background: "#f8f8f8",
            border: "1px solid #ddd",
            borderRadius: "10px",
          }}
        >
          <h3>
            {clickedBuild.pokemon} —{" "}
            {clickedBuild.month}
          </h3>

          {Object.entries(
            clickedBuild.data
          ).map(([category, items]) => (
            <div key={category}>
              <strong>{category}</strong>
              <ul>
                {items.map((item, idx) => (
                  <li key={idx}>
                    {item.name} (
                    {item.usage}%)
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}

      <canvas ref={canvasRef}></canvas>
    </div>
  );
}
